-- =====================================================================
--  MovilCenter · Catálogo inicial (productos de ejemplo)
--  Ejecutar después de 01_esquema.sql. Luego edita precios, stock y
--  fotos desde Supabase > Table Editor > productos.
-- =====================================================================
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.productos','id'), (select max(id) from public.productos));
